import React from 'react';
import { TrendingUp, TrendingDown, LucideIcon } from 'lucide-react';

interface KpiCardProps {
  title: string;
  value: string | number;
  deltaPercent?: number;
  deltaLabel?: string;
  icon: LucideIcon;
  accentColor?: string;
}

export const KpiCard: React.FC<KpiCardProps> = ({
  title,
  value,
  deltaPercent = 0,
  deltaLabel = 'vs. periodo anterior',
  icon: Icon,
  accentColor = 'text-cyan-400'
}) => {
  const isPositive = deltaPercent >= 0;

  return (
    <div className="relative overflow-hidden rounded-xl border border-white/10 bg-slate-900/60 p-5 backdrop-blur-xl shadow-lg transition-all duration-300 hover:border-cyan-500/30 hover:shadow-cyan-500/10">
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium uppercase tracking-wider text-slate-400">{title}</span>
        <div className={`p-2 rounded-lg bg-white/5 border border-white/10 ${accentColor}`}>
          <Icon className="h-5 w-5" />
        </div>
      </div>
      <div className="mt-4 flex items-baseline justify-between">
        <h3 className="text-2xl font-bold tracking-tight text-white font-display">{value}</h3>
        {deltaPercent !== undefined && (
          <div className={`flex items-center text-xs font-semibold ${isPositive ? 'text-emerald-400' : 'text-rose-400'}`}>
            {isPositive ? <TrendingUp className="mr-1 h-3.5 w-3.5" /> : <TrendingDown className="mr-1 h-3.5 w-3.5" />}
            <span>{isPositive ? `+${deltaPercent}%` : `${deltaPercent}%`}</span>
          </div>
        )}
      </div>
      <p className="mt-1 text-[11px] text-slate-500">{deltaLabel}</p>
      <div className="absolute -right-8 -bottom-8 h-24 w-24 rounded-full bg-cyan-500/10 blur-2xl pointer-events-none" />
    </div>
  );
};

