import React, { useState } from 'react';
import { X, DollarSign, Percent, ShieldCheck } from 'lucide-react';

interface PricingModalProps {
  isOpen: boolean;
  onClose: () => void;
  productName: string;
  baseCost: number;
  currentPrice: number;
  onApplyPrice: (newPrice: number) => void;
}

export const PricingModal: React.FC<PricingModalProps> = ({
  isOpen,
  onClose,
  productName,
  baseCost,
  currentPrice,
  onApplyPrice
}) => {
  const [price, setPrice] = useState(currentPrice);
  if (!isOpen) return null;

  const margin = price > 0 ? ((price - baseCost) / price) * 100 : 0;
  const isHealthyMargin = margin >= 18;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
      <div className="relative w-full max-w-lg rounded-2xl border border-white/15 bg-slate-900/90 p-6 shadow-2xl backdrop-blur-2xl animate-in fade-in zoom-in-95 duration-200">
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-400 hover:text-white transition-colors">
          <X className="h-5 w-5" />
        </button>
        <h3 className="text-lg font-bold text-white font-display">Ajuste de Precio B2B</h3>
        <p className="text-xs text-slate-400 mt-1">{productName}</p>

        <div className="mt-6 grid grid-cols-2 gap-4">
          <div className="rounded-xl border border-white/10 bg-white/5 p-3">
            <span className="text-[11px] text-slate-400 uppercase font-medium">Costo Base</span>
            <p className="text-lg font-bold text-slate-200 mt-1">${baseCost.toLocaleString('es-CO')}</p>
          </div>
          <div className={`rounded-xl border p-3 ${isHealthyMargin ? 'border-emerald-500/30 bg-emerald-500/10' : 'border-amber-500/30 bg-amber-500/10'}`}>
            <span className="text-[11px] uppercase font-medium text-slate-300">Margen Bruto</span>
            <p className={`text-lg font-bold mt-1 ${isHealthyMargin ? 'text-emerald-400' : 'text-amber-400'}`}>
              {margin.toFixed(1)}%
            </p>
          </div>
        </div>

        <div className="mt-6">
          <label className="block text-xs font-medium text-slate-300 mb-2">Nuevo Precio de Venta (COP)</label>
          <div className="relative">
            <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <input
              type="number"
              value={price}
              onChange={(e) => setPrice(Number(e.target.value))}
              className="w-full rounded-xl border border-white/15 bg-slate-950/80 pl-9 pr-4 py-2.5 text-sm text-white focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 outline-none"
            />
          </div>
        </div>

        <div className="mt-6 flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 text-xs font-medium text-slate-300 hover:text-white">
            Cancelar
          </button>
          <button
            onClick={() => { onApplyPrice(price); onClose(); }}
            className="flex items-center gap-2 rounded-xl bg-gradient-to-r from-indigo-600 to-cyan-600 px-5 py-2 text-xs font-semibold text-white shadow-lg hover:brightness-110 active:scale-95 transition-all"
          >
            <ShieldCheck className="h-4 w-4" />
            Confirmar Precio
          </button>
        </div>
      </div>
    </div>
  );
};
